/**
 * @summary Send SMS (simulated in demo)
 */
export const getSendSmsUrl = () => {
  return `/api/sms`;
};

export const sendSms = async (
  smsRequest: SmsRequest,
  options?: RequestInit,
): Promise<MessageResponse> => {
  return customFetch<MessageResponse>(getSendSmsUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(smsRequest),
  });
};

export const getSendSmsMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof sendSms>>,
    TError,
    { data: BodyType<SmsRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof sendSms>>,
  TError,
  { data: BodyType<SmsRequest> },
  TContext
> => {
  const mutationKey = ["sendSms"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof sendSms>>,
    { data: BodyType<SmsRequest> }
  > = (props) => {
    const { data } = props ?? {};

    return sendSms(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type SendSmsMutationResult = NonNullable<
  Awaited<ReturnType<typeof sendSms>>
>;
export type SendSmsMutationBody = BodyType<SmsRequest>;
